from roboid import * hamster = Hamster() 
LEFT = 0 RIGHT = 1 UP = 2 DOWN = 3 class Mover: def __init__(self) : self.reset() def reset(self) : self.x = 1 self.y = 1 self.direction = RIGHT def turn_to_left(self) : if self.direction == RIGHT : hamster.board_left() hamster.board_left() elif self.direction == UP : 
hamster.board_left() elif self.direction == DOWN : hamster.board_right() self.direction = LEFT
